/* Vecta offline support. Generated by build_site.py. */
const CACHE = "vecta-app-9ec5a55b48";          // the app itself: saved on the first visit
const LESSONS = "vecta-lessons-a507090628";  // lessons: saved by "Download all lessons" or when played
const FILES = [
 "./",
 "KaTeX_AMS-Regular.woff2",
 "KaTeX_Caligraphic-Bold.woff2",
 "KaTeX_Caligraphic-Regular.woff2",
 "KaTeX_Fraktur-Bold.woff2",
 "KaTeX_Fraktur-Regular.woff2",
 "KaTeX_Main-Bold.woff2",
 "KaTeX_Main-BoldItalic.woff2",
 "KaTeX_Main-Italic.woff2",
 "KaTeX_Main-Regular.woff2",
 "KaTeX_Math-BoldItalic.woff2",
 "KaTeX_Math-Italic.woff2",
 "KaTeX_SansSerif-Bold.woff2",
 "KaTeX_SansSerif-Italic.woff2",
 "KaTeX_SansSerif-Regular.woff2",
 "KaTeX_Script-Regular.woff2",
 "KaTeX_Size1-Regular.woff2",
 "KaTeX_Size2-Regular.woff2",
 "KaTeX_Size3-Regular.woff2",
 "KaTeX_Size4-Regular.woff2",
 "KaTeX_Typewriter-Regular.woff2",
 "app.css",
 "benchmark.json",
 "board.js",
 "cmp_144.png",
 "cmp_240.png",
 "cmp_vecta.png",
 "icon-192.png",
 "icon-512.png",
 "index.html",
 "katex.min.css",
 "katex.min.js",
 "lessons.json",
 "manifest.webmanifest",
 "player.js",
 "record.html",
 "record.js",
 "results.html",
 "results.js",
 "store.js"
];

self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});
self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE && k !== LESSONS).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// Audio players ask for byte ranges; serve them from a saved whole file.
async function partial(req, res) {
  const buf = await res.arrayBuffer(), n = buf.byteLength;
  const m = /bytes=(\d*)-(\d*)/.exec(req.headers.get("range") || "");
  let a = 0, b = n - 1;
  if (m) {
    if (m[1] === "" && m[2] !== "") a = Math.max(0, n - Number(m[2]));
    else { a = Number(m[1] || 0); if (m[2] !== "") b = Math.min(Number(m[2]), n - 1); }
  }
  if (a >= n) return new Response(null, { status: 416, headers: { "Content-Range": "bytes */" + n } });
  return new Response(buf.slice(a, b + 1), { status: 206, headers: {
    "Content-Type": res.headers.get("Content-Type") || "application/octet-stream",
    "Content-Range": "bytes " + a + "-" + b + "/" + n, "Content-Length": String(b - a + 1), "Accept-Ranges": "bytes" } });
}

self.addEventListener("fetch", e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== location.origin) return;
  url.search = "";
  const isLesson = /-(lesson\.json|voice\.(opus|m4a))$/.test(url.pathname);
  e.respondWith((async () => {
    const hit = await caches.match(url.href);
    if (hit) return req.headers.has("range") ? partial(req, hit) : hit;
    if (isLesson) {
      // Fetch the whole file once, save it, then answer (ranges included) from the saved copy.
      const res = await fetch(url.href);
      if (res.status === 200) {
        await (await caches.open(LESSONS)).put(url.href, res.clone());
        return req.headers.has("range") ? partial(req, res) : res;
      }
      return res;
    }
    return fetch(req);
  })());
});
